<template>
  <AdminLayout>
    <main class="mx-auto max-w-7xl space-y-6" aria-labelledby="users-title">
      <header class="flex flex-col gap-4 rounded-2xl bg-slate-900 p-5 text-white shadow-sm sm:p-6 lg:flex-row lg:items-end lg:justify-between">
        <div><p class="text-xs font-bold uppercase tracking-[.16em] text-blue-300">SEGURIDAD Y ACCESO</p><h1 id="users-title" class="mt-1 text-3xl font-black tracking-tight">Administración de usuarios</h1><p class="mt-2 max-w-2xl text-sm text-slate-300">Gestiona cuentas, accesos y estado de los usuarios del sistema.</p></div>
        <button type="button" class="min-h-11 rounded-lg bg-blue-500 px-4 font-bold text-white transition hover:bg-blue-400 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white disabled:cursor-not-allowed disabled:opacity-60 sm:self-start lg:self-auto" :disabled="loading || saving" @click="openCreate"><i class="pi pi-user-plus mr-2" aria-hidden="true"></i>Nuevo usuario</button>
      </header>

      <section class="grid gap-3 sm:grid-cols-2 lg:grid-cols-4" aria-label="Resumen de usuarios"><article class="rounded-xl border border-slate-200 bg-white p-4 shadow-sm"><div class="flex items-center justify-between"><span class="text-sm font-semibold text-slate-500">Total de usuarios</span><i class="pi pi-users rounded-lg bg-blue-50 p-2 text-blue-700" aria-hidden="true"></i></div><strong class="mt-2 block text-3xl font-black text-slate-900">{{ safeNumber(pagination.total) }}</strong><p class="mt-1 text-xs text-slate-500">Resultado global del listado</p></article></section>

      <form class="rounded-2xl bg-white p-4 shadow-sm" aria-label="Filtros de usuarios" @submit.prevent="apply"><div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-[minmax(0,1.6fr)_minmax(10rem,.7fr)_minmax(10rem,.7fr)_auto]"><label class="text-sm font-semibold text-slate-700">Buscar<div class="relative mt-1"><i class="pi pi-search pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" aria-hidden="true"></i><input v-model.trim="filters.search" class="field pl-10" placeholder="Nombre o correo" autocomplete="off" /></div></label><label class="text-sm font-semibold text-slate-700">Estado<select v-model="filters.status" class="field mt-1"><option value="">Todos los estados</option><option value="active">Activo</option><option value="inactive">Inactivo</option></select></label><label class="text-sm font-semibold text-slate-700">Tipo de usuario<select v-model="filters.role" class="field mt-1"><option value="">Todos los tipos</option><option value="admin">Administrador</option><option value="customer">Cliente</option><option value="treasury">Tesorería</option></select></label><div class="flex flex-wrap items-end gap-2"><button class="action-primary" :disabled="loading" type="submit"><i class="pi pi-filter mr-2" aria-hidden="true"></i>Aplicar</button><button class="action-secondary" :disabled="loading" type="button" @click="clear"><i class="pi pi-times mr-2" aria-hidden="true"></i>Limpiar</button><button class="icon-button" :disabled="loading" type="button" aria-label="Actualizar usuarios" data-tooltip="Actualizar" @click="load()"><i class="pi pi-refresh" :class="{ 'pi-spin': loading }" aria-hidden="true"></i></button></div></div></form>

      <p v-if="message" class="rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-900" aria-live="polite"><i class="pi pi-check-circle mr-2" aria-hidden="true"></i>{{ message }}</p>
      <section v-if="error" class="rounded-2xl border border-red-200 bg-red-50 p-5 text-red-900" role="alert"><h2 class="font-bold"><i class="pi pi-exclamation-circle mr-2" aria-hidden="true"></i>No se pudo cargar usuarios</h2><p class="mt-1 text-sm">{{ error }}</p><button type="button" class="mt-3 rounded-lg border border-red-300 px-3 py-2 text-sm font-bold" @click="load()">Reintentar</button></section>

      <section v-else class="overflow-hidden rounded-2xl bg-white shadow-sm"><div class="overflow-x-auto"><table class="w-full min-w-[760px] text-left text-sm"><thead class="bg-slate-100 text-xs font-bold uppercase tracking-wide text-slate-600"><tr><th scope="col" class="p-4">Usuario</th><th scope="col" class="p-4">Correo</th><th scope="col" class="p-4">Tipo</th><th scope="col" class="p-4">Estado</th><th scope="col" class="p-4">Registro</th><th scope="col" class="p-4 text-right">Acciones</th></tr></thead><tbody>
        <template v-if="loading"><tr v-for="row in 5" :key="row" class="border-t"><td v-for="cell in 6" :key="cell" class="p-4"><div class="h-5 animate-pulse rounded bg-slate-200" :class="cell === 1 ? 'w-40' : 'w-24'"></div></td></tr></template>
        <template v-else-if="users.length"><tr v-for="user in users" :key="user.id" class="border-t border-slate-100 transition hover:bg-slate-50" :class="{ 'opacity-70': !user.is_active }"><td class="p-4"><div class="flex items-center gap-3"><span class="flex h-10 w-10 shrink-0 items-center justify-center rounded-full text-xs font-black" :class="avatarTone(user.name)">{{ initials(user.name) }}</span><div class="min-w-0"><span class="block truncate font-semibold text-slate-900">{{ user.name || 'Sin nombre' }}</span><span v-if="user.id === authStore.user?.id" class="mt-1 inline-flex rounded-full bg-blue-100 px-2 py-0.5 text-xs font-bold text-blue-800">Tú</span></div></div></td><td class="max-w-52 p-4"><span class="inline-flex max-w-full items-center gap-2 truncate text-slate-600" :title="user.email"><i class="pi pi-envelope text-xs text-slate-400" aria-hidden="true"></i><span class="truncate">{{ user.email || '—' }}</span></span></td><td class="p-4"><span class="badge" :class="roleTone(user.role)"><i :class="roleIcon(user.role)" aria-hidden="true"></i>{{ roleLabel(user.role) }}</span></td><td class="p-4"><span class="badge" :class="user.is_active ? 'badge-active' : 'badge-inactive'"><i :class="user.is_active ? 'pi pi-check-circle' : 'pi pi-ban'" aria-hidden="true"></i>{{ statusLabel(user.is_active) }}</span></td><td class="whitespace-nowrap p-4 text-slate-600">{{ formatDate(user.created_at) }}</td><td class="p-4"><div class="flex justify-end gap-1"><button type="button" class="icon-button text-blue-700" aria-label="Editar usuario" data-tooltip="Editar usuario" :disabled="saving" @click="openEdit(user)"><i class="pi pi-pencil" aria-hidden="true"></i></button><button type="button" class="icon-button text-amber-700" aria-label="Restablecer contraseña" data-tooltip="Restablecer contraseña" :disabled="saving" @click="openPassword(user)"><i class="pi pi-key" aria-hidden="true"></i></button><button v-if="user.is_active" type="button" class="icon-button text-red-700" aria-label="Desactivar usuario" :data-tooltip="user.id === authStore.user?.id ? 'No puedes desactivar tu propia cuenta' : 'Desactivar usuario'" :disabled="saving || user.id === authStore.user?.id" @click="confirmStatus(user)"><i class="pi pi-ban" aria-hidden="true"></i></button><button v-else type="button" class="icon-button text-emerald-700" aria-label="Reactivar usuario" data-tooltip="Reactivar usuario" :disabled="saving" @click="confirmStatus(user)"><i class="pi pi-check-circle" aria-hidden="true"></i></button></div></td></tr></template>
        <tr v-else><td colspan="6" class="p-12 text-center"><i :class="hasFilters ? 'pi pi-search' : 'pi pi-users'" class="mb-3 text-3xl text-slate-400" aria-hidden="true"></i><p class="font-bold text-slate-700">{{ hasFilters ? 'No encontramos usuarios con estos filtros' : 'Todavía no hay usuarios registrados' }}</p><p class="mt-1 text-sm text-slate-500">{{ hasFilters ? 'Prueba limpiando o ajustando los filtros.' : 'Crea la primera cuenta desde este panel.' }}</p><button type="button" class="mt-4 rounded-lg bg-blue-700 px-4 py-2 text-sm font-bold text-white" @click="hasFilters ? clear() : openCreate()">{{ hasFilters ? 'Limpiar filtros' : 'Nuevo usuario' }}</button></td></tr>
      </tbody></table></div><footer class="flex flex-col gap-3 border-t border-slate-100 px-4 py-4 text-sm sm:flex-row sm:items-center sm:justify-between"><span class="text-slate-600">{{ paginationSummary }}</span><div class="flex items-center gap-2"><button type="button" class="pager-button" :disabled="!pagination.prev_page_url || loading" @click="load(safePage(pagination.current_page - 1))"><i class="pi pi-angle-left" aria-hidden="true"></i>Anterior</button><span class="whitespace-nowrap text-slate-600">Página {{ safePage(pagination.current_page) }} de {{ totalPages }}</span><button type="button" class="pager-button" :disabled="!pagination.next_page_url || loading" @click="load(safePage(pagination.current_page + 1))">Siguiente<i class="pi pi-angle-right" aria-hidden="true"></i></button></div></footer></section>

      <div v-if="modal" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/60 p-3" role="dialog" aria-modal="true" :aria-labelledby="modalTitle"><form class="max-h-[94vh] w-full max-w-xl overflow-y-auto rounded-2xl bg-white shadow-2xl" @submit.prevent="save"><header class="flex items-start gap-3 border-b border-slate-100 p-5"><span class="flex h-10 w-10 items-center justify-center rounded-xl" :class="mode === 'password' ? 'bg-amber-100 text-amber-800' : 'bg-blue-100 text-blue-800'"><i :class="mode === 'password' ? 'pi pi-key' : mode === 'create' ? 'pi pi-user-plus' : 'pi pi-user-edit'" aria-hidden="true"></i></span><div class="min-w-0 flex-1"><h2 :id="modalTitle" class="text-xl font-black text-slate-900">{{ modalHeading }}</h2><p class="mt-1 text-sm text-slate-600">{{ modalDescription }}</p></div><button type="button" class="icon-button" aria-label="Cerrar modal" data-tooltip="Cerrar" @click="closeModal"><i class="pi pi-times" aria-hidden="true"></i></button></header><div class="space-y-4 p-5"><template v-if="mode !== 'password'"><div class="grid gap-4 sm:grid-cols-2"><label class="form-label">Nombre<input v-model.trim="form.name" required class="field mt-1" autocomplete="name" /></label><label class="form-label">Correo<input v-model.trim="form.email" required type="email" class="field mt-1" autocomplete="email" /></label><label class="form-label">Teléfono<input v-model.trim="form.phone" class="field mt-1" autocomplete="tel" /></label><label class="form-label">Tipo<select v-model="form.role" class="field mt-1"><option value="customer">Cliente</option><option value="admin">Administrador</option><option value="treasury">Tesorería</option></select></label><label v-if="form.role !== 'treasury'" class="flex items-center gap-2 text-sm font-semibold text-slate-700"><input v-model="form.can_deliver" type="checkbox" /> Habilitación legada de reparto</label><p v-else class="rounded-lg bg-slate-50 p-3 text-sm text-slate-600">Tesorería no utiliza la habilitación legada de reparto.</p><label v-if="mode === 'create'" class="flex items-center gap-2 text-sm font-semibold text-slate-700"><input v-model="form.is_active" type="checkbox" /> Cuenta activa</label><template v-if="mode === 'create'"><label class="form-label">Contraseña<input v-model="form.password" required :type="showPasswords ? 'text' : 'password'" class="field mt-1" autocomplete="new-password" /></label><label class="form-label">Confirmación<input v-model="form.password_confirmation" required :type="showPasswords ? 'text' : 'password'" class="field mt-1" autocomplete="new-password" /></label></template></div></template><template v-else><label class="form-label">Nueva contraseña<input v-model="form.password" required :type="showPasswords ? 'text' : 'password'" class="field mt-1" autocomplete="new-password" /></label><label class="form-label">Confirmación<input v-model="form.password_confirmation" required :type="showPasswords ? 'text' : 'password'" class="field mt-1" autocomplete="new-password" /></label></template><label v-if="mode === 'create' || mode === 'password'" class="flex items-center gap-2 text-sm text-slate-600"><input v-model="showPasswords" type="checkbox" /> Mostrar contraseñas</label><p v-if="modalError" class="rounded-lg bg-red-50 p-3 text-sm text-red-800" role="alert">{{ modalError }}</p></div><footer class="flex justify-end gap-3 border-t border-slate-100 p-5"><button type="button" class="action-secondary" :disabled="saving" @click="closeModal">Cancelar</button><button class="action-primary" :disabled="saving">{{ saving ? 'Guardando…' : modalAction }}</button></footer></form></div>
    </main>
  </AdminLayout>
</template>

<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue';
import { useConfirm } from 'primevue/useconfirm';
import AdminLayout from '@/layouts/AdminLayout.vue';
import api from '@/api';
import { useAuthStore } from '@/stores/auth';

const authStore = useAuthStore(), confirm = useConfirm();
const users = ref([]), pagination = ref({}), loading = ref(false), saving = ref(false), error = ref(''), message = ref(''), modalError = ref(''), modal = ref(false), mode = ref('create'), selected = ref({}), showPasswords = ref(false);
const filters = reactive({ search: '', status: '', role: '' });
const blank = () => ({ name: '', email: '', phone: '', role: 'customer', can_deliver: false, is_active: true, password: '', password_confirmation: '' });
const form = reactive(blank()); const modalTitle = 'user-modal-title';
const hasFilters = computed(() => Object.values(filters).some(value => value !== ''));
const totalPages = computed(() => Math.max(1, Number(pagination.value.last_page) || 1));
const paginationSummary = computed(() => { const total = Number(pagination.value.total) || 0; if (!total) return 'Sin usuarios para mostrar'; const from = Number(pagination.value.from) || 0, to = Number(pagination.value.to) || 0; return `Mostrando ${from}–${to} de ${total} usuarios`; });
const modalHeading = computed(() => mode.value === 'create' ? 'Nuevo usuario' : mode.value === 'edit' ? 'Editar usuario' : 'Restablecer contraseña');
const modalDescription = computed(() => mode.value === 'password' ? `Las sesiones activas de ${selected.value.name || 'este usuario'} se cerrarán.` : 'Completa únicamente los datos autorizados para esta cuenta.');
const modalAction = computed(() => mode.value === 'password' ? 'Restablecer contraseña' : mode.value === 'create' ? 'Crear usuario' : 'Guardar cambios');
function safeNumber(value) { const number = Number(value); return Number.isFinite(number) ? number.toLocaleString('es-PE') : '0'; }
function safePage(value) { const number = Number(value); return Number.isFinite(number) && number > 0 ? Math.min(Math.trunc(number), totalPages.value) : 1; }
function initials(name) { return String(name || '').trim().split(/\s+/).filter(Boolean).slice(0, 2).map(part => part.charAt(0).toUpperCase()).join('') || 'US'; }
function avatarTone(name) { const tones = ['bg-blue-100 text-blue-800', 'bg-violet-100 text-violet-800', 'bg-teal-100 text-teal-800', 'bg-amber-100 text-amber-800']; const hash = [...String(name || '')].reduce((sum, char) => sum + char.charCodeAt(0), 0); return tones[hash % tones.length]; }
function roleLabel(role) { return role === 'admin' ? 'Administrador' : role === 'treasury' ? 'Tesorería' : 'Cliente'; }
function roleTone(role) { return role === 'admin' ? 'badge-admin' : role === 'treasury' ? 'badge-treasury' : 'badge-customer'; }
function roleIcon(role) { return role === 'admin' ? 'pi pi-shield' : role === 'treasury' ? 'pi pi-wallet' : 'pi pi-user'; }
function statusLabel(active) { return active ? 'Activo' : 'Inactivo'; }
function formatDate(value) { const date = new Date(value); return value && !Number.isNaN(date.getTime()) ? new Intl.DateTimeFormat('es-PE', { dateStyle: 'medium', timeZone: 'America/Lima' }).format(date) : '—'; }
function errorMessage(exception) { return exception.response?.data?.message || Object.values(exception.response?.data?.errors || {}).flat().join(' ') || 'No se pudo completar la operación.'; }
function params(page) { return Object.fromEntries(Object.entries({ ...filters, page }).filter(([, value]) => value !== '' && value !== null && value !== undefined)); }
function copy(data) { Object.assign(form, blank(), data); if (form.role === 'treasury') form.can_deliver = false; }
function closeModal() { Object.assign(form, blank()); showPasswords.value = false; modalError.value = ''; selected.value = {}; modal.value = false; }
async function load(page = 1) { if (loading.value) return; loading.value = true; error.value = ''; try { const { data } = await api.get('/admin/users', { params: params(page) }); users.value = data.data || []; pagination.value = data.meta || {}; } catch (exception) { error.value = errorMessage(exception); } finally { loading.value = false; } }
function apply() { load(1); }
function clear() { Object.assign(filters, { search: '', status: '', role: '' }); load(1); }
function openCreate() { mode.value = 'create'; copy({}); showPasswords.value = false; modalError.value = ''; modal.value = true; }
function openEdit(user) { mode.value = 'edit'; selected.value = user; copy(user); showPasswords.value = false; modalError.value = ''; modal.value = true; }
function openPassword(user) { mode.value = 'password'; selected.value = user; copy({}); showPasswords.value = false; modalError.value = ''; modal.value = true; }
async function save() { if (saving.value) return; saving.value = true; modalError.value = ''; try { if (mode.value === 'create') await api.post('/admin/users', form); else if (mode.value === 'edit') await api.put(`/admin/users/${selected.value.id}`, form); else await api.put(`/admin/users/${selected.value.id}/password`, { password: form.password, password_confirmation: form.password_confirmation }); message.value = mode.value === 'password' ? 'Contraseña restablecida y sesiones revocadas.' : 'Usuario guardado.'; closeModal(); await load(safePage(pagination.value.current_page)); } catch (exception) { modalError.value = errorMessage(exception); } finally { saving.value = false; } }
function confirmStatus(user) { if (saving.value || user.id === authStore.user?.id) return; confirm.require({ header: user.is_active ? 'Desactivar usuario' : 'Reactivar usuario', message: user.is_active ? `Desactivarás a ${user.name}. Sus sesiones activas se cerrarán.` : `Reactivarás a ${user.name}; deberá iniciar sesión nuevamente.`, icon: user.is_active ? 'pi pi-exclamation-triangle' : 'pi pi-check-circle', acceptLabel: user.is_active ? 'Desactivar' : 'Reactivar', rejectLabel: 'Cancelar', acceptClass: user.is_active ? 'p-button-danger' : 'p-button-success', accept: () => toggleStatus(user) }); }
async function toggleStatus(user) { if (saving.value) return; saving.value = true; error.value = ''; try { await api.patch(`/admin/users/${user.id}/status`, { is_active: !user.is_active }); message.value = 'Estado actualizado.'; await load(safePage(pagination.value.current_page)); } catch (exception) { error.value = errorMessage(exception); } finally { saving.value = false; } }
onMounted(load);
watch(() => form.role, role => { if (role === 'treasury') form.can_deliver = false; });
</script>

<style scoped>
.field{min-height:2.75rem;width:100%;border:1px solid #cbd5e1;border-radius:.625rem;background:#fff;padding:.625rem .75rem;color:#0f172a}.field:focus,.icon-button:focus-visible,.action-primary:focus-visible,.action-secondary:focus-visible,.pager-button:focus-visible{outline:2px solid #2563eb;outline-offset:2px}.action-primary,.action-secondary,.pager-button,.icon-button{min-height:2.5rem;border-radius:.625rem;font-size:.875rem;font-weight:700;transition:.15s}.action-primary{background:#2563eb;padding:.625rem 1rem;color:#fff}.action-primary:hover{background:#1d4ed8}.action-secondary,.pager-button{border:1px solid #cbd5e1;background:#fff;padding:.625rem .875rem;color:#334155}.action-secondary:hover,.pager-button:hover{background:#f8fafc}.icon-button{position:relative;display:inline-flex;height:2.5rem;width:2.5rem;align-items:center;justify-content:center;border:1px solid #e2e8f0;background:#fff}.icon-button:hover{background:#f8fafc}.icon-button:disabled,.action-primary:disabled,.action-secondary:disabled,.pager-button:disabled{cursor:not-allowed;opacity:.5}.icon-button[data-tooltip]::after{content:attr(data-tooltip);pointer-events:none;position:absolute;right:0;top:calc(100% + .4rem);z-index:70;display:none;white-space:nowrap;border-radius:.375rem;background:#0f172a;padding:.35rem .55rem;font-size:.75rem;font-weight:600;color:#fff;box-shadow:0 4px 12px rgb(15 23 42 / .25)}.icon-button[data-tooltip]:hover::after,.icon-button[data-tooltip]:focus-visible::after{display:block}.badge{display:inline-flex;align-items:center;gap:.35rem;border-radius:9999px;padding:.3rem .55rem;font-size:.75rem;font-weight:700}.badge-admin{background:#ede9fe;color:#5b21b6}.badge-customer{background:#eef2ff;color:#3730a3}.badge-treasury{background:#ecfccb;color:#3f6212}.badge-active{background:#dcfce7;color:#166534}.badge-inactive{background:#f1f5f9;color:#475569}.form-label{display:block;font-size:.875rem;font-weight:700;color:#334155}@media(max-width:639px){.icon-button[data-tooltip]::after{display:none}}
</style>
